arguments.file_text:
@* Step progress indicator bar *@

<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="d-flex justify-content-between list-unstyled mb-0 position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var status = GetStepStatus(step);
            <li class="step-item flex-fill text-center @status">
                <button class="step-button border-0 bg-transparent p-0 w-100"
                        disabled="@(status == "future")"
                        @onclick="() => OnStepClicked.InvokeAsync(step)">
                    <span class="step-circle d-inline-flex align-items-center justify-content-center rounded-circle mb-1">
                        @if (status == "completed")
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @step
                        }
                    </span>
                    <span class="step-label d-block small">@StepNames[i]</span>
                </button>
                @if (step < StepNames.Length)
                {
                    <div class="step-connector"></div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = default!;
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "current";
        if (CompletedSteps.Contains(step)) return "completed";
        return "future";
    }
}

.step-indicator ol {
    counter-reset: step;
}

.step-item {
    position: relative;
}

.step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.875rem;
    font-weight: 600;
    border: 2px solid #dee2e6;
    color: #6c757d;
    background: #fff;
    transition: all 0.2s ease;
}

.step-item.current .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    color: #6c757d;
}

.step-item.current .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-button {
    cursor: pointer;
}

.step-button:disabled {
    cursor: default;
    opacity: 0.6;
}

.step-connector {
    position: absolute;
