    z-index: 0;
}

.step-item.completed .step-connector {
    background: #198754;
}

@inject IApplicationService ApplicationService

<EditForm Model="Personal" OnValidSubmit="HandleNext" FormName="personal-info-step">
    <DataAnnotationsValidator />

    <h4 class="mb-3">Personal Information</h4>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Full Name</label>
            <InputText class="form-control" @bind-Value="Personal.FullName" />
            <ValidationMessage For="() => Personal.FullName" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Email Address</label>
            <InputText class="form-control" @bind-Value="Personal.Email" />
            <ValidationMessage For="() => Personal.Email" />
            @if (!string.IsNullOrEmpty(emailError))
            {
                <div class="text-danger small mt-1">@emailError</div>
            }
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone Number</label>
            <InputText class="form-control" @bind-Value="Personal.Phone" />
            <ValidationMessage For="() => Personal.Phone" />
        </div>
        <div class="col-12">
            <label class="form-label">Address</label>
            <InputTextArea class="form-control" @bind-Value="Personal.Address" rows="2" />
            <ValidationMessage For="() => Personal.Address" />
        </div>
    </div>

    <div class="d-flex justify-content-end mt-4">
        <button type="submit" class="btn btn-primary" disabled="@isValidating">
            @if (isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                <span>Validating…</span>
            }
            else
            {
                <span>Next &raquo;</span>
            }
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter] public EventCallback OnCompleted { get; set; }

    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        emailError = null;
        isValidating = true;

        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Personal.Email);
            if (!isValid)
            {
                emailError = "This email address could not be verified.";
                return;
            }

            await OnCompleted.InvokeAsync();
        }
        finally
        {
            isValidating = false;
        }
    }
}

@* Step progress indicator bar *@

<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="d-flex justify-content-between list-unstyled mb-0 position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var status = GetStepStatus(step);
            <li class="step-item flex-fill text-center @status">
                <button class="step-button border-0 bg-transparent p-0 w-100"
                        disabled="@(status == "future")"
                        @onclick="() => OnStepClicked.InvokeAsync(step)">
                    <span class="step-circle d-inline-flex align-items-center justify-content-center rounded-circle mb-1">
                        @if (status == "completed")
                        {
                            <span>&#10003;</span>
                        }
                        else
                        {
                            @step
                        }
                    </span>
                    <span class="step-label d-block small">@StepNames[i]</span>
                </button>
                @if (step < StepNames.Length)
                {
                    <div class="step-connector"></div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = default!;
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "current";
        if (CompletedSteps.Contains(step)) return "completed";
        return "future";
    }
}

