arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (applicationId.HasValue)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">&#10003; Application Submitted!</h3>
            <p class="lead">Your application has been received.</p>
            <p class="mb-0"><strong>Application ID: @applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="mt-4">
            @switch (currentStep)
            {
                case 1:
                    <PersonalInfoStep Personal="personalInfo"
                                      OnCompleted="() => CompleteStep(1)" />
                    break;

                case 2:
                    <WorkHistoryStep Entries="workEntries"
                                     OnBack="() => GoToStep(currentStep - 1)"
                                     OnCompleted="() => CompleteStep(2)" />
                    break;

                case 3:
                    <ReferencesStep References="references"
                                    OnBack="() => GoToStep(currentStep - 1)"
                                    OnCompleted="() => CompleteStep(3)" />
                    break;

                case 4:
                    <CoverLetterStep @bind-CoverLetter="coverLetter"
                                     OnBack="() => GoToStep(currentStep - 1)"
                                     OnCompleted="() => CompleteStep(4)" />
                    break;

                case 5:
                    <ReviewStep Personal="personalInfo"
                                WorkEntries="workEntries"
                                References="references"
                                CoverLetter="coverLetter"
                                IsSubmitting="isSubmitting"
                                ErrorMessage="submissionError"
                                OnEditSection="GoToStep"
                                OnBack="() => GoToStep(currentStep - 1)"
                                OnSubmit="SubmitApplication" />
                    break;
            }
        </div>
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new() };
