@using System.ComponentModel.DataAnnotations

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <EditForm Model="Entries[index]" id="@($"work-entry-{index}")">
        <DataAnnotationsValidator />
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    </EditForm>
}

@if (validationErrors.Count > 0)
{
    <div class="alert alert-danger">Please fill in all required fields for each position.</div>
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">
        &laquo; Back
    </button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">
        Next &raquo;
    </button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnCompleted { get; set; }

    private List<ValidationResult> validationErrors = new();

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationErrors.Clear();
        foreach (var entry in Entries)
        {
            var context = new ValidationContext(entry);
            Validator.TryValidateObject(entry, context, validationErrors, true);
        }

        if (validationErrors.Count == 0)
        {
            await OnCompleted.InvokeAsync();
        }
    }
}

@using System.ComponentModel.DataAnnotations

<h4 class="mb-3">References</h4>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <EditForm Model="References[index]" id="@($"reference-{index}")">
        <DataAnnotationsValidator />
        <ReferenceForm Reference="References[index]"
                       Index="index"
                       CanRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    </EditForm>
}

@if (validationErrors.Count > 0)
{
    <div class="alert alert-danger">Please fill in all required fields for each reference.</div>
}

@if (References.Count < MaxReferences)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">
        &laquo; Back
    </button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">
        Next &raquo;
    </button>
</div>

@code {
    private const int MaxReferences = 3;

    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnCompleted { get; set; }

    private List<ValidationResult> validationErrors = new();

    private void AddReference()
    {
        if (References.Count < MaxReferences)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        validationErrors.Clear();
        foreach (var reference in References)
        {
            var context = new ValidationContext(reference);
            Validator.TryValidateObject(reference, context, validationErrors, true);
        }

        if (validationErrors.Count == 0)
        {
            await OnCompleted.InvokeAsync();
        }
    }
}

